        static readonly int[][] ByHalfword = Build();

        static int[][] Build()
        {
            var t = new int[65536][];
            var l = new List<int>();
            for(var hw = 0u; hw < 65536; hw++)
            {
                l.Clear();
                var len = (hw >> 13) == 7 ? 4 : 2;
                for(var i = 0; i < Patterns.Length; i++)
                {
                    var p = Patterns[i];
                    if(p.len == len && ((hw << 16) & p.mask & 0xFFFF0000u) == (p.value & 0xFFFF0000u))
                    {
                        l.Add(i);
                    }
                }
                t[hw] = l.ToArray();
            }
            return t;
        }

